-- Seed data awal. Jalankan setelah supabase/schema.sql.
insert into public.categories (name, slug) values
  ('Compressor', 'compressor'),
  ('Condensor', 'condensor'),
  ('Evaporator', 'evaporator'),
  ('CDU Set', 'cdu-set'),
  ('Axial Fan', 'axial-fan'),
  ('Spare Part', 'spare-part'),
  ('Accessories', 'accessories')
on conflict (slug) do update set name = excluded.name;

insert into public.products (slug, name, category_id, price, discount_price, short_description, description, images)
select v.slug, v.name, c.id, v.price, v.discount_price, v.short_description, v.description, v.images::jsonb
from (values
  ('cdu-set-compressor-condensor', 'CDU Set Compressor & Condensor', 'cdu-set', 24500000, 21500000, 'Condensing unit set lengkap yang sudah dirakit pada satu rangka baja: compressor semi-hermetic, condenser udara berpendingin dua kipas, suction accumulator di sisi kiri, liquid receiver horizontal di bawah, sampai filter drier berwarna hitam pada jalur liquid line. Tiga gauge tekanan dan kontrol tekanan sudah terpasang di panel, sehingga kondisi unit bisa langsung dibaca tanpa membuka rangka.', 'Kapasitas unit ini dipasangkan untuk cold storage menengah, freezer room, maupun instalasi industri yang butuh suhu medium sampai low temperature. Refrigeran yang didukung R-404A maupun R-507, tegangan 380 volt tiga fase, dan kompresor semi-hermetic body besi tuang yang tidak mudah bocor pada bagian las saat bekerja lama. Dimensi keseluruhan sekitar 2200 × 1200 × 1650 mm dengan bobot total di atas 800 kg, jadi pengiriman dilakukan dalam bentuk crating kayu dengan pallet.

Unit dikirim sudah disegel dari pabrik dan tinggal dipasang di lokasi. Tim kami dapat menyiapkan kapasitas sesuai volume ruangan, frekuensi buka-tutup pintu, dan beban produk yang masuk, termasuk membantu commissioning sampai suhu ruangan stabil.', '["https://res.cloudinary.com/wuetxgqp/image/upload/v1792925391/wkx8tgjiyegb5f01uxq4.jpg"]'),
  ('compressor-semi-hermetic', 'Compressor Semi-Hermetic', 'compressor', 14750000, null, 'Compressor semi-hermetic untuk sistem refrigerasi komersial maupun industri. Body terbuat dari besi tuang yang menghalangi kebocoran refrigeran pada bagian las, sehingga lebih aman dibanding jenis bolted ketika unit bekerja sepanjang hari operasional.', 'Unit dikemas dalam peti kayu dengan pipa suction dan discharge yang sudah dibungkus isolasi hitam, sehingga sambungan aman selama pengiriman. Tersedia untuk dua arah tata pipa, dan electrical box pada bagian atas sudah berlabel peringatan keselamatan. Kapasitas yang paling banyak dicari mulai dari 3 HP sampai 10 HP, dengan dukungan refrigeran R-404A, R-507, R-22, maupun R-134a tergantung kebutuhan aplikasi.

Komponen ini banyak dipakai untuk membangun CDU set baru, mengganti kompresor lama yang kapasitasnya sudah turun, maupun menambah kapasitas pendinginan pada sistem yang berjalan. Karena kapasitas sangat menentukan, kirimkan volume ruangan dan target suhunya melalui WhatsApp agar tim kami bisa merekomendasikan ukuran yang pas.', '["https://res.cloudinary.com/wuetxgqp/image/upload/v1792925395/ptihr7ngeaayv54hhmsx.jpg"]'),
  ('condensor-air-cooled', 'Condensor Air Cooled', 'condensor', 4350000, null, 'Condenser udara untuk membuang panas kondensasi dari sistem refrigerasi. Rangkanya berupa casing hijau yang tahan cuaca dengan dua unit kipas axial pada bagian depan, sehingga aliran udara melewati coil dan suhu refrigeran turun sebelum kembali ke kompresor.', 'Pipa masuk dan keluar berupa sambungan tembaga di sisi samping, mudah disambung ke jalur liquid maupun discharge line. Coil terbuat dari fin aluminium yang tidak berkarat di lingkungan lembap, dan casingnya dapat dipasang pada dinding luar, di atas plafon semi-outdoor, maupun di area terbuka dengan jarak sirkulasi udara yang cukup.

Kapasitas yang tersedia mulai dari unit dua kipas sampai unit dengan beberapa kipas berdiameter lebih besar. Untuk menentukan ukuran yang tepat, tim kami perlu tahu kapasitas kompresor, jenis refrigeran, serta suhu ambient lokasi pemasangan.', '["https://res.cloudinary.com/wuetxgqp/image/upload/v1792925395/gyqprsx2f8njpryklwie.webp"]'),
  ('evaporator-air-cooler', 'Evaporator Air Cooler', 'evaporator', 6900000, 6200000, 'Evaporator berupa unit air cooler yang dipasang pada plafon ruangan pendingin. Casing putih dengan dua sampai tiga unit kipas axial di bagian depan, dan coil fin aluminium yang terlihat melalui sela kipas. Bagian bawah dilengkapi drip tray untuk menampung air defrost sehingga tidak menetes ke produk di bawahnya.', 'Tersedia dalam dua varian: tiga kipas untuk ruangan lebih besar, dan dua kipas untuk ruangan menengah. Model plafon ini membebaskan lantai ruangan sehingga rak, palet, dan jalur forklift tetap maksimal. Defrost dapat dilakukan secara otomatis, jadi teknisi tidak perlu membuka unit secara berkala untuk membersihkan salju beku pada coil.

Kapasitas yang didukung mulai dari medium temperature sampai low temperature, dengan refrigeran R-404A maupun R-507. Saat commissioning kami kalibrasi laju aliran udara supaya suhu di sisi jauh ruangan tidak tertinggal jauh dari sisi dekat pintu.', '["https://res.cloudinary.com/wuetxgqp/image/upload/v1792925397/xetdskgl5jf3a2h66zjy.png"]'),
  ('axial-fan-condenser', 'Axial Fan Condenser', 'axial-fan', 1250000, null, 'Axial fan untuk kondenser maupun evaporator. Bilahnya terbuat dari baja galvanis yang melengkung ke arah tertentu untuk menghasilkan dorongan udara yang besar dengan kebisingan rendah, dan dilindungi wire guard berupa kawat konsentris yang melingkari seluruh diameter.', 'Bagian tengahnya terdiri dari housing motor yang tercast dari besi, dengan lubang pasang standar sehingga mudah diganti dengan ukuran yang sama. Fan ini cocok dipakai pada unit condenser udara, air cooler ruangan pendingin, maupun ventilasi gudang yang membutuhkan aliran udara konstan.

Kapasitas yang tersedia mulai dari diameter 300 mm sampai 500 mm, dengan daya motor dan putaran yang menyesuaikan. Karena dimensi sangat menentukan, kirimkan foto fan lama beserta diameternya agar tim kami bisa mencarikan unit yang kompatibel.', '["https://res.cloudinary.com/wuetxgqp/image/upload/v1792925399/peyktvgvcdijknynmlsd.jpg"]'),
  ('piston-kit-reciprocating', 'Piston Kit Compressor Reciprocating', 'spare-part', 1480000, null, 'Piston kit untuk kompresor reciprocating. Dalam satu paket sudah termasuk piston aluminium berkepala datar dengan alur ring, connecting rod berbahan aluminium yang di bagian ujung kecilnya sudah dipasangi bushing kuningan, piston pin berlubang, serta seal berupa O-ring untuk mencegah kebocoran oil.', 'Part ini dibutuhkan saat kapasitas pendinginan kompresor menurun drastis akibat keausan segel pada dinding silinder. Karena seluruh bagian dirakit dalam satu toleransi yang sama, hasil penyusutan kembali kompresor tetap optimal setelah penggantian. Kondisi baru, bukan part bekas ulang, dan dikemas pada kardus pelindung agar permukaan piston tidak lecet selama pengiriman.

Tersedia untuk beberapa seri kompresor reciprocating yang umum beredar. Jika tidak yakin dengan nomor rangka kompresor, kirimkan fotonya melalui WhatsApp dan tim kami akan cek kompatibilitasnya sebelum memesan.', '["https://res.cloudinary.com/wuetxgqp/image/upload/v1792925400/emsuywrgkui3m1ejdnas.jpg"]'),
  ('compressor-terminal-plate', 'Terminal Plate Compressor', 'accessories', 890000, null, 'Terminal plate untuk kelistrikan kompresor. Basisnya terbuat dari pelat baja berlapis yang dipres rapi, dengan tiga pasang busbar kuningan berulir di tengahnya untuk hubungan tiga fase listrik, serta seal berupa baut ulir berlapis baja pada setiap lubang pemasangan.', 'Komponen ini menjadi bagian kritis dari kompresor, karena kebocoran refrigeran paling sering terjadi pada jalur listrik bila terminal plate aus atau seal-nya tidak rapat. Saat melakukan perbaikan, plate lama yang sudah berkarat atau terminalnya melengkung sebaiknya diganti sekalian, karena menahan biaya tambahan nanti bila harus membongkar kompresor lagi.

Tersedia untuk beberapa tipe kompresor semi-hermetic dan reciprocating. Karena bentuknya sangat menentukan kecocokan, kirimkan nomor rangka kompresor Anda agar tim kami bisa memastikan spesifikasi yang benar.', '["https://res.cloudinary.com/wuetxgqp/image/upload/v1792925401/wjwq3srrqoizxutmxqh1.jpg"]'),
  ('valve-plate-set-reciprocating', 'Valve Plate Set Compressor Reciprocating', 'spare-part', 1950000, null, 'Valve plate set untuk kompresor reciprocating. Paketnya berisi pelat katup aluminium dengan pola lubang presisi yang tinggi, dilengkapi deretan katup reed berwarna merah untuk saluran suction maupun biru untuk saluran discharge, serta pegas pengunci pada tiap katup.', 'Bagian ini mengatur aliran refrigeran masuk dan keluar dari silinder kompresor. Bila katupnya aus, bengkok, atau tidak rata pada tempat duduknya, tekanan kompresor langsung turun dan suhu ruangan tidak pernah stabil meski kompresor tetap berbunyi. Karena itu setiap kali membongkar kompresor untuk perbaikan besar, valve plate sebaiknya diganti sekalian.

Paket dikirim lengkap dengan seluruh katup dan pegasnya, sehingga teknisi tidak perlu memesan part satu per satu. Tim kami dapat membantu memastikan kompatibilitas berdasarkan nomor rangka kompresor Anda sebelum pemesanan.', '["https://res.cloudinary.com/wuetxgqp/image/upload/v1792925401/knbzth9xcymb1touizkn.webp"]')
) as v(slug, name, category_slug, price, discount_price, short_description, description, images)
join public.categories c on c.slug = v.category_slug
on conflict (slug) do nothing;
